UPDATE public.quizzes SET questions = questions || '[{"id": 501, "question": "Dossier n\u00b0501 : Quelle est la dur\u00e9e l\u00e9gale du travail hebdomadaire en France ?", "options": ["35 heures par semaine", "39 heures par semaine", "40 heures par semaine", "44 heures par semaine"], "correct_index": 0, "reference": "Art. L3121-27", "article": "La dur\u00e9e l\u00e9gale du travail effectif des salari\u00e9s \u00e0 temps complet est fix\u00e9e \u00e0 trente-cinq heures par semaine.", "casus": "[Dossier 501] Un salari\u00e9 dans une entreprise de logistique effectue 39 heures de travail effectif. Comment sont d\u00e9compt\u00e9es les heures au-del\u00e0 de la dur\u00e9e l\u00e9gale ?"}, {"id": 502, "question": "Dossier n\u00b0502 : Quelle est la dur\u00e9e maximale initiale de la p\u00e9riode d''essai pour un cadre ?", "options": ["4 mois", "3 mois", "2 mois", "6 mois"], "correct_index": 0, "reference": "Art. L1221-19", "article": "Le contrat de travail \u00e0 dur\u00e9e ind\u00e9termin\u00e9e peut comporter une p\u00e9riode d''essai dont la dur\u00e9e maximale est de : 1\u00b0 Deux mois pour les ouvriers et les employ\u00e9s ; 2\u00b0 Trois mois pour les agents de ma\u00eetrise et les techniciens ; 3\u00b0 Quatre mois pour les cadres.", "casus": "[Dossier 502] Un cadre est recrut\u00e9 en CDI. Son contrat mentionne une p\u00e9riode d''essai."}, {"id": 503, "question": "Dossier n\u00b0503 : La rupture conventionnelle peut-elle \u00eatre impos\u00e9e par l''une des parties ?", "options": ["Non, elle doit r\u00e9sulter d''un commun accord", "Oui, par l''employeur uniquement", "Oui, par le salari\u00e9 uniquement", "Seulement apr\u00e8s 2 ans d''anciennet\u00e9"], "correct_index": 0, "reference": "Art. L1237-11", "article": "L''employeur et le salari\u00e9 peuvent convenir d''un commun accord des conditions de la rupture du contrat de travail qui les lie. La rupture conventionnelle [...] ne peut \u00eatre impos\u00e9e par l''une ou l''autre des parties.", "casus": "[Dossier 503] Un employeur souhaite se s\u00e9parer d''un salari\u00e9 sans licenciement."}, {"id": 504, "question": "Dossier n\u00b0504 : Combien de jours de cong\u00e9s pay\u00e9s un salari\u00e9 acquiert-il par mois ?", "options": ["2,5 jours ouvrables", "2 jours ouvrables", "1,5 jours ouvrables", "3 jours ouvrables"], "correct_index": 0, "reference": "Art. L3141-3", "article": "Le salari\u00e9 a droit \u00e0 un cong\u00e9 de deux jours et demi ouvrables par mois de travail effectif chez le m\u00eame employeur.", "casus": "[Dossier 504] Un salari\u00e9 travaille depuis 1 an \u00e0 temps complet."}, {"id": 505, "question": "Dossier n\u00b0505 : Qu''est-ce qui caract\u00e9rise le harc\u00e8lement moral selon la loi ?", "options": ["Des agissements r\u00e9p\u00e9t\u00e9s d\u00e9gradant les conditions", "Une simple m\u00e9sentente ponctuelle", "Une pression li\u00e9e \u00e0 un retard", "Un changement de poste l\u00e9gal"], "correct_index": 0, "reference": "Art. L1152-1", "article": "Aucun salari\u00e9 ne doit subir les agissements r\u00e9p\u00e9t\u00e9s de harc\u00e8lement moral qui ont pour objet ou pour effet une d\u00e9gradation de ses conditions de travail...", "casus": "[Dossier 505] Un salari\u00e9 subit des remarques humiliantes quotidiennes."}, {"id": 506, "question": "Dossier n\u00b0506 : Un CDD peut-il \u00eatre conclu pour pourvoir un emploi durable ?", "options": ["Non, seulement pour une t\u00e2che pr\u00e9cise et temporaire", "Oui, si le salari\u00e9 est d''accord", "Oui, sans limitation", "Seulement pour les cadres"], "correct_index": 0, "reference": "Art. L1242-2", "article": "Le contrat de travail \u00e0 dur\u00e9e d\u00e9termin\u00e9e ne peut \u00eatre conclu que pour l''ex\u00e9cution d''une t\u00e2che pr\u00e9cise et temporaire...", "casus": "[Dossier 506] Une entreprise veut embaucher pour un surcro\u00eet d''activit\u00e9."}, {"id": 507, "question": "Dossier n\u00b0507 : Le paiement du salaire doit-il \u00eatre mensuel pour la plupart des salari\u00e9s ?", "options": ["Oui, la mensualisation est la r\u00e8gle", "Non, c''est au choix de l''employeur", "C''est obligatoirement par quinzaine", "C''est \u00e0 la journ\u00e9e"], "correct_index": 0, "reference": "Art. L3242-1", "article": "La r\u00e9mun\u00e9ration est mensuelle. Elle est ind\u00e9pendante, pour un horaire de travail effectif d\u00e9termin\u00e9, du nombre de jours travaill\u00e9s dans le mois.", "casus": "[Dossier 507] Un salari\u00e9 est pay\u00e9 chaque mois le m\u00eame montant malgr\u00e9 les jours f\u00e9ri\u00e9s."}, {"id": 508, "question": "Dossier n\u00b0508 : Que doit imp\u00e9rativement avoir un licenciement pour motif personnel ?", "options": ["Une cause r\u00e9elle et s\u00e9rieuse", "L''accord de l''inspection du travail", "L''accord des d\u00e9l\u00e9gu\u00e9s syndicaux", "Un pr\u00e9avis de 6 mois minimum"], "correct_index": 0, "reference": "Art. L1232-1", "article": "Tout licenciement pour motif personnel est motiv\u00e9. Il est justifi\u00e9 par une cause r\u00e9elle et s\u00e9rieuse.", "casus": "[Dossier 508] Un employeur licencie un salari\u00e9 pour insuffisance professionnelle."}, {"id": 509, "question": "Dossier n\u00b0509 : Quelle est la dur\u00e9e minimale de la pause apr\u00e8s 6h de travail ?", "options": ["20 minutes", "10 minutes", "30 minutes", "15 minutes"], "correct_index": 0, "reference": "Art. L3121-33", "article": "D\u00e8s que le temps de travail quotidien atteint six heures, le salari\u00e9 b\u00e9n\u00e9ficie d''un temps de pause d''une dur\u00e9e minimale de vingt minutes.", "casus": "[Dossier 509] Un ouvrier travaille 7 heures cons\u00e9cutives."}, {"id": 510, "question": "Dossier n\u00b0510 : Quelle est la mission principale du CSE ?", "options": ["L''expression collective des salari\u00e9s", "Le recrutement des cadres uniquement", "La gestion comptable de l''entreprise", "La fixation des salaires individuels"], "correct_index": 0, "reference": "Art. L2312-1", "article": "Le comit\u00e9 social et \u00e9conomique a pour mission d''assurer une expression collective des salari\u00e9s permettant la prise en compte permanente de leurs int\u00e9r\u00eats...", "casus": "[Dossier 510] Une entreprise de 60 salari\u00e9s souhaite mettre en place un CSE."}, {"id": 511, "question": "Dossier n\u00b0511 : Quelle est la dur\u00e9e l\u00e9gale du travail hebdomadaire en France ?", "options": ["35 heures par semaine", "39 heures par semaine", "40 heures par semaine", "44 heures par semaine"], "correct_index": 0, "reference": "Art. L3121-27", "article": "La dur\u00e9e l\u00e9gale du travail effectif des salari\u00e9s \u00e0 temps complet est fix\u00e9e \u00e0 trente-cinq heures par semaine.", "casus": "[Dossier 511] Un salari\u00e9 dans une entreprise de logistique effectue 39 heures de travail effectif. Comment sont d\u00e9compt\u00e9es les heures au-del\u00e0 de la dur\u00e9e l\u00e9gale ?"}, {"id": 512, "question": "Dossier n\u00b0512 : Quelle est la dur\u00e9e maximale initiale de la p\u00e9riode d''essai pour un cadre ?", "options": ["4 mois", "3 mois", "2 mois", "6 mois"], "correct_index": 0, "reference": "Art. L1221-19", "article": "Le contrat de travail \u00e0 dur\u00e9e ind\u00e9termin\u00e9e peut comporter une p\u00e9riode d''essai dont la dur\u00e9e maximale est de : 1\u00b0 Deux mois pour les ouvriers et les employ\u00e9s ; 2\u00b0 Trois mois pour les agents de ma\u00eetrise et les techniciens ; 3\u00b0 Quatre mois pour les cadres.", "casus": "[Dossier 512] Un cadre est recrut\u00e9 en CDI. Son contrat mentionne une p\u00e9riode d''essai."}, {"id": 513, "question": "Dossier n\u00b0513 : La rupture conventionnelle peut-elle \u00eatre impos\u00e9e par l''une des parties ?", "options": ["Non, elle doit r\u00e9sulter d''un commun accord", "Oui, par l''employeur uniquement", "Oui, par le salari\u00e9 uniquement", "Seulement apr\u00e8s 2 ans d''anciennet\u00e9"], "correct_index": 0, "reference": "Art. L1237-11", "article": "L''employeur et le salari\u00e9 peuvent convenir d''un commun accord des conditions de la rupture du contrat de travail qui les lie. La rupture conventionnelle [...] ne peut \u00eatre impos\u00e9e par l''une ou l''autre des parties.", "casus": "[Dossier 513] Un employeur souhaite se s\u00e9parer d''un salari\u00e9 sans licenciement."}, {"id": 514, "question": "Dossier n\u00b0514 : Combien de jours de cong\u00e9s pay\u00e9s un salari\u00e9 acquiert-il par mois ?", "options": ["2,5 jours ouvrables", "2 jours ouvrables", "1,5 jours ouvrables", "3 jours ouvrables"], "correct_index": 0, "reference": "Art. L3141-3", "article": "Le salari\u00e9 a droit \u00e0 un cong\u00e9 de deux jours et demi ouvrables par mois de travail effectif chez le m\u00eame employeur.", "casus": "[Dossier 514] Un salari\u00e9 travaille depuis 1 an \u00e0 temps complet."}, {"id": 515, "question": "Dossier n\u00b0515 : Qu''est-ce qui caract\u00e9rise le harc\u00e8lement moral selon la loi ?", "options": ["Des agissements r\u00e9p\u00e9t\u00e9s d\u00e9gradant les conditions", "Une simple m\u00e9sentente ponctuelle", "Une pression li\u00e9e \u00e0 un retard", "Un changement de poste l\u00e9gal"], "correct_index": 0, "reference": "Art. L1152-1", "article": "Aucun salari\u00e9 ne doit subir les agissements r\u00e9p\u00e9t\u00e9s de harc\u00e8lement moral qui ont pour objet ou pour effet une d\u00e9gradation de ses conditions de travail...", "casus": "[Dossier 515] Un salari\u00e9 subit des remarques humiliantes quotidiennes."}, {"id": 516, "question": "Dossier n\u00b0516 : Un CDD peut-il \u00eatre conclu pour pourvoir un emploi durable ?", "options": ["Non, seulement pour une t\u00e2che pr\u00e9cise et temporaire", "Oui, si le salari\u00e9 est d''accord", "Oui, sans limitation", "Seulement pour les cadres"], "correct_index": 0, "reference": "Art. L1242-2", "article": "Le contrat de travail \u00e0 dur\u00e9e d\u00e9termin\u00e9e ne peut \u00eatre conclu que pour l''ex\u00e9cution d''une t\u00e2che pr\u00e9cise et temporaire...", "casus": "[Dossier 516] Une entreprise veut embaucher pour un surcro\u00eet d''activit\u00e9."}, {"id": 517, "question": "Dossier n\u00b0517 : Le paiement du salaire doit-il \u00eatre mensuel pour la plupart des salari\u00e9s ?", "options": ["Oui, la mensualisation est la r\u00e8gle", "Non, c''est au choix de l''employeur", "C''est obligatoirement par quinzaine", "C''est \u00e0 la journ\u00e9e"], "correct_index": 0, "reference": "Art. L3242-1", "article": "La r\u00e9mun\u00e9ration est mensuelle. Elle est ind\u00e9pendante, pour un horaire de travail effectif d\u00e9termin\u00e9, du nombre de jours travaill\u00e9s dans le mois.", "casus": "[Dossier 517] Un salari\u00e9 est pay\u00e9 chaque mois le m\u00eame montant malgr\u00e9 les jours f\u00e9ri\u00e9s."}, {"id": 518, "question": "Dossier n\u00b0518 : Que doit imp\u00e9rativement avoir un licenciement pour motif personnel ?", "options": ["Une cause r\u00e9elle et s\u00e9rieuse", "L''accord de l''inspection du travail", "L''accord des d\u00e9l\u00e9gu\u00e9s syndicaux", "Un pr\u00e9avis de 6 mois minimum"], "correct_index": 0, "reference": "Art. L1232-1", "article": "Tout licenciement pour motif personnel est motiv\u00e9. Il est justifi\u00e9 par une cause r\u00e9elle et s\u00e9rieuse.", "casus": "[Dossier 518] Un employeur licencie un salari\u00e9 pour insuffisance professionnelle."}, {"id": 519, "question": "Dossier n\u00b0519 : Quelle est la dur\u00e9e minimale de la pause apr\u00e8s 6h de travail ?", "options": ["20 minutes", "10 minutes", "30 minutes", "15 minutes"], "correct_index": 0, "reference": "Art. L3121-33", "article": "D\u00e8s que le temps de travail quotidien atteint six heures, le salari\u00e9 b\u00e9n\u00e9ficie d''un temps de pause d''une dur\u00e9e minimale de vingt minutes.", "casus": "[Dossier 519] Un ouvrier travaille 7 heures cons\u00e9cutives."}, {"id": 520, "question": "Dossier n\u00b0520 : Quelle est la mission principale du CSE ?", "options": ["L''expression collective des salari\u00e9s", "Le recrutement des cadres uniquement", "La gestion comptable de l''entreprise", "La fixation des salaires individuels"], "correct_index": 0, "reference": "Art. L2312-1", "article": "Le comit\u00e9 social et \u00e9conomique a pour mission d''assurer une expression collective des salari\u00e9s permettant la prise en compte permanente de leurs int\u00e9r\u00eats...", "casus": "[Dossier 520] Une entreprise de 60 salari\u00e9s souhaite mettre en place un CSE."}, {"id": 521, "question": "Dossier n\u00b0521 : Quelle est la dur\u00e9e l\u00e9gale du travail hebdomadaire en France ?", "options": ["35 heures par semaine", "39 heures par semaine", "40 heures par semaine", "44 heures par semaine"], "correct_index": 0, "reference": "Art. L3121-27", "article": "La dur\u00e9e l\u00e9gale du travail effectif des salari\u00e9s \u00e0 temps complet est fix\u00e9e \u00e0 trente-cinq heures par semaine.", "casus": "[Dossier 521] Un salari\u00e9 dans une entreprise de logistique effectue 39 heures de travail effectif. Comment sont d\u00e9compt\u00e9es les heures au-del\u00e0 de la dur\u00e9e l\u00e9gale ?"}, {"id": 522, "question": "Dossier n\u00b0522 : Quelle est la dur\u00e9e maximale initiale de la p\u00e9riode d''essai pour un cadre ?", "options": ["4 mois", "3 mois", "2 mois", "6 mois"], "correct_index": 0, "reference": "Art. L1221-19", "article": "Le contrat de travail \u00e0 dur\u00e9e ind\u00e9termin\u00e9e peut comporter une p\u00e9riode d''essai dont la dur\u00e9e maximale est de : 1\u00b0 Deux mois pour les ouvriers et les employ\u00e9s ; 2\u00b0 Trois mois pour les agents de ma\u00eetrise et les techniciens ; 3\u00b0 Quatre mois pour les cadres.", "casus": "[Dossier 522] Un cadre est recrut\u00e9 en CDI. Son contrat mentionne une p\u00e9riode d''essai."}, {"id": 523, "question": "Dossier n\u00b0523 : La rupture conventionnelle peut-elle \u00eatre impos\u00e9e par l''une des parties ?", "options": ["Non, elle doit r\u00e9sulter d''un commun accord", "Oui, par l''employeur uniquement", "Oui, par le salari